def f(inputs: List[Tuple[int, int, int, int, int, int]]):
    '''
    inputs: a list of tuples, where each tuple contains six integers
    '''
    result = []
    for y1, m1, d1, y2, m2, d2 in inputs:
        if y1 < 0 or y2 < 0:
            break
        day = (d2 - d1) + (365 * (y2 - y1))
        if m2 < m1:
            day += 365 * (m1 - m2)
        elif m2 == m1:
            day += 31 * (d2 - d1)
        if day <= 0:
            result.append('0')
        elif day >= 366:
            result.append('1')
        else:
            result.append(f'{day // 7}')
    return '\n'.join(result)
